//! UDM local fault-injection test server (dev only).
//!
//! Everything binds `127.0.0.1` and never contacts the internet. Fixtures are
//! generated by code (see [`fixture`]).
//!
//! HTTP routes (plain and TLS server):
//! - `/files/<name>?<faults>` — fixture with Range/If-Range support. Faults:
//!   `drop_after=N[&drop_times=K]`, `ignore_range=1`, `bad_content_range=1`,
//!   `short_length=1`, `long_length=1`, `slow=BPS`, `extra_bytes=N`, `no_range=1`,
//!   `no_length=1`, `stall=1`, `endless_headers=1`, `huge_header=1`, `gzip=1`,
//!   `weak_etag=1`, `no_validators=1`, `rst_after=N[&drop_times=K]`.
//! - `/redirect/<n>/files/<name>`, `/redirect-loop`, `/redirect-abs?to=<pct url>`,
//!   `/downgrade[/files/<name>]`, `/disposition?v=<pct value>&file=<name>`,
//!   `/auth/basic/files/<name>`, `/auth/digest/files/<name>`,
//!   `/site/index.html` (+ `p1.html`..`p6.html`), `/maze/<n>.html?fan=K` (endless
//!   site for grabber limits), `/status/<code>`.

mod fixture;
mod ftp;
mod h2srv;
mod http1;
mod plan;
mod proxy;
mod server;
mod tls;
mod util;

